(()=>{document.addEventListener("DOMContentLoaded",()=>{let n=document.querySelectorAll("[data-ws-sale-countdown]");n.length&&n.forEach(e=>{let o=parseInt(e.dataset.endTime,10);if(!o)return;let a=e.querySelector("[data-ws-countdown-days]"),r=e.querySelector("[data-ws-countdown-hours]"),s=e.querySelector("[data-ws-countdown-minutes]"),d=e.querySelector("[data-ws-countdown-seconds]"),c=()=>{let l=Math.floor(Date.now()/1e3),t=o-l;if(t<=0){t=0,e.classList.add("is-expired"),clearInterval(i),window.location.reload();return}let u=Math.floor(t/86400);t%=86400;let S=Math.floor(t/3600);t%=3600;let f=Math.floor(t/60),m=t%60;a&&(a.textContent=String(u).padStart(2,"0")),r&&(r.textContent=String(S).padStart(2,"0")),s&&(s.textContent=String(f).padStart(2,"0")),d&&(d.textContent=String(m).padStart(2,"0"))};c();let i=setInterval(c,1e3)})});})();
